/**
 * Copies the Prisma artifacts that `tsc` cannot emit.
 *
 * `src/prisma/schema.d.ts` is a hand-maintained declaration file (generated by
 * `prisma contract emit`) and `schema.prisma` is the contract source. Neither is
 * an emitted module, so the compiler leaves them behind and the published
 * `dist/prisma/use-prisma.d.ts` would reference a missing `./schema.d.js`.
 * `schema.json` is emitted by `tsc` because the module imports it.
 */
import { copyFileSync, existsSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const root = join(here, "..");
const source = join(root, "src", "prisma");
const target = join(root, "dist", "prisma");

const artifacts = ["schema.d.ts", "schema.prisma"];

mkdirSync(target, { recursive: true });

for (const file of artifacts) {
	const from = join(source, file);
	if (!existsSync(from)) {
		console.error(`copy-prisma-artifacts: missing ${from}`);
		process.exit(1);
	}
	copyFileSync(from, join(target, file));
	console.log(`copy-prisma-artifacts: ${file} → dist/prisma/`);
}
